<?php $ptab = 'bills'; require __DIR__ . '/purch_tabs.php'; $paid = 0; foreach ($pays as $p) { $paid += (float) $p['amount']; } $left = round((float) $b['amount'] - $paid, 2); ?>
<div class="top"><div><h2 style="margin:0">Bill <?= e($b['bill_no']) ?> <?= badge($b['status'] === 'paid' ? 'Paid' : ($b['status'] === 'void' ? 'Void' : 'Open'), $b['status'] === 'paid' ? 'p-ok' : ($b['status'] === 'void' ? 'p-bad' : 'p-warn')) ?></h2><span class="muted"><?= e($b['sname']) ?><?= $b['ponumber'] ? ' &middot; PO ' . e($b['ponumber']) : '' ?></span></div><a class="btn alt" href="/staff/bills">&larr; Bills</a></div>
<div class="grid g2" style="align-items:start"><div class="card"><dl class="kv"><dt>Bill date</dt><dd><?= e(fmt_date($b['bill_date'])) ?></dd><dt>Due</dt><dd class="<?= $b['status'] === 'open' && $b['due_date'] < date('Y-m-d') ? 'overdue' : '' ?>"><?= e(fmt_date($b['due_date'])) ?></dd><dt>Total</dt><dd><?= e(money($b['amount'])) ?> <span class="muted">(GST <?= e(money($b['gst_amount'])) ?>)</span></dd><dt>Paid</dt><dd><?= e(money($paid)) ?></dd><dt>Balance</dt><dd><b><?= e(money($left)) ?></b></dd><dt>Notes</dt><dd><?= e((string) $b['notes']) ?></dd></dl>
<?php if ($b['status'] === 'open' && $paid == 0): ?><form method="post" class="mt"><?= csrf_field() ?><input type="hidden" name="action" value="void"><button class="btn danger sm" data-confirm="Void this bill?">Void bill</button></form><?php endif; ?></div>
<div><?php if ($b['status'] === 'open'): ?><div class="card mb"><h3>Record a payment</h3><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="pay"><div class="row"><div><label>Amount (max <?= e(money($left)) ?>)</label><input name="amount" inputmode="decimal" required value="<?= e(number_format($left, 2, '.', '')) ?>"></div><div><label>Date</label><input type="date" name="paid_on" value="<?= e(date('Y-m-d')) ?>" required></div></div><div class="row"><div><label>Method</label><select name="method"><?= options(BILL_METHODS) ?></select></div><div><label>Reference</label><input name="ref" maxlength="60"></div></div><button class="btn">Record payment</button></form></div><?php endif; ?>
<div class="card"><h3>Payments</h3><?php foreach ($pays as $p): ?><div class="comment"><?= e(money($p['amount'])) ?> &middot; <?= e(fmt_date($p['paid_on'])) ?> &middot; <?= e($p['method']) ?><?= $p['ref'] ? ' &middot; ' . e($p['ref']) : '' ?><br><span class="who"><?= e((string) $p['uname']) ?></span></div><?php endforeach; if (!$pays): ?><p class="muted">No payments yet.</p><?php endif; ?></div></div></div>
